def Solve(n):
    a=-1
    b=1000000000
    while(b-a>1):
        e=(b+a)//2
        x=(e*(e+1))//2
        if(x>=n):
            b=e
        else:
            a=e
    x = b * (b + 1) // 2
    if (x - n) % 2 == 0:
        return b
    x2 = (b + 1) * (b + 2) // 2
    if (x2 - n) % 2 == 0:
        return b + 1
    return b + 2


x=int(input())
x=abs(x)
print(Solve(x))

#!/usr/bin/env python

import math

def findJumps (dest, jumps, l, maxHops) :
    if (len(l) > maxHops) :
        return []
    if (dest == sum(l)) :
        return l

    l1 = l[:]
    l2 = l[:]
    l1.append(jumps + 1)
    l2.append(-(jumps + 1))

    ret = findJumps (dest, jumps + 1, l1, maxHops)
    if (len(ret) > 0) :
        return ret
    return findJumps (dest, jumps + 1, l2, maxHops)

maxHops = 5
def findShortest (dest) :
    dest = abs(dest)
    if dest == 0:
        return []

    def total(k):
        return k * (k + 1) // 2

    def check(a, b):
        return (a % 2) == (b % 2)

    n = (-1 + (1 + 8 * dest) ** 0.5) / 2
    ceil_n = math.ceil(n)

    if check(total(ceil_n), dest):
        k = ceil_n
    elif check(total(ceil_n + 1), dest):
        k = ceil_n + 1
    else:
        k = ceil_n + 2

    return [0] * k

dest = int(input())
print(len(findShortest(dest)))
